import { IngestionEventTrackingDTO } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.dto.';
import { IngestionEventTrackingService } from '@/modules/ingestion-event-tracking/ingestion-event-tracking.service';

@Injectable()
export class DaprServiceApi implements OnModuleInit {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return { method, object, plant, service: DaprServiceApi.name, userId };
  }

  private plantList: Array<PlantsResponseDto> = [];

  private readonly daprClient: DaprClient;

  public constructor(
    private readonly mappingService: MappingService,
    private readonly eventEmitter: EventEmitter2,
    private readonly mutexManagerService: MutexManagerService,
    private readonly redisConfigService: RedisConfigService,
    private readonly ingestionEventTrackingService: IngestionEventTrackingService,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly customLogger: AppLogger,
  ) {
    this.daprClient = new DaprClient();
  }

  public async onModuleInit(): Promise<void> {
    await this.initializePlant();
  }

  public async initializePlant(): Promise<void> {
    const context = DaprServiceApi.createLogContext('initializePlant');

    try {
      this.plantList = await getListPlant(
        this.customLogger,
        this.daprClient,
        this.subscribeMessageService,
        this.redisConfigService.redisStoreAmr,
        this.redisConfigService.redisPlantKey,
      );
      this.customLogger.log(
        `Updated Plants List: ${JSON.stringify(this.plantList)}`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Failed to get plant list: ${error.message}`,
        context,
        error,
      );
    }
  }

  private async acquireIngestionLock(
    lockKey: string,
    plant: number,
    context: JobsLogContext,
  ): Promise<(() => void) | undefined> {
    const operationInfo = {
      name: 'Acquire lock for ingestion tracking',
      srcLocation: 'processMessage',
    };

    return execAndLog(
      this.customLogger,
      context,
      () =>
        acquireLockManagerWithTimeout(
          this.customLogger,
          context,
          this.mutexManagerService,
          lockKey,
        ),
      operationInfo,
      { lockKey, plant },
    );
  }

  private async trackIngestionEvent(
    ingestionEventTracking: IngestionEventTrackingDTO,
    context: JobsLogContext,
    plant: number,
    lockKey: string,
  ): Promise<boolean> {
    const operationDetails = { lockKey, plant };

    const valid = await execAndLog(
      this.customLogger,
      context,
      () =>
        validateAndTrackChanges(
          this.customLogger,
          this.ingestionEventTrackingService,
          ingestionEventTracking,
        ),
      {
        name: 'Validate and track ingestionEventTracking',
        srcLocation: 'processMessage',
      },
      operationDetails,
    );

    if (!valid) return false;

    await execAndLog(
      this.customLogger,
      context,
      () =>
        this.ingestionEventTrackingService.upsertCache(ingestionEventTracking),
      {
        name: 'Upsert ingestionEventTracking cache',
        srcLocation: 'processMessage',
      },
      operationDetails,
    );

    return true;
  }

  private async processMessage(
    message: RedisMessage,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    const { mappedData, destination, operation } = message;
    const plant = mappedData?.plant;
    const context = DaprServiceApi.createLogContext('processMessage', plant);
    this.customLogger.debug(
      `============== ${sequenceNumber} start processing message =======================`,
      context,
    );
    try {
      if (!operation) return;

      // If (operation !== 'r' && ingestionEventTracking) {
      //   Const lockKey = ingestionEventTracking.hashKey;
      //   This.customLogger.log(`Acquiring lock for key ${lockKey}`, context);

      //   Const release = await this.acquireIngestionLock(
      //     LockKey,
      //     Plant,
      //     Context,
      //   );
      //   If (!release) {
      //     This.customLogger.error(
      //       `Error: Failed to acquire lock for ${lockKey}, skipping ingestion tracking.`,
      //       Context,
      //     );
      //     Return;
      //   }

      //   Try {
      //     Const success = await this.trackIngestionEvent(
      //       IngestionEventTracking,
      //       Context,
      //       Plant,
      //       LockKey,
      //     );
      //     If (!success) return;
      //   } finally {
      //     This.customLogger.log(`Releasing lock for ${lockKey}`, context);
      //     Release();
      //   }
      // }
      await emitSqlEvent(
        this.customLogger,
        context,
        this.eventEmitter,
        destination,
        mappedData,
        operation,
      );
      this.customLogger.debug(
        `============== ${sequenceNumber} After Emit event =======================`,
        context,
      );
    } catch (error) {
      this.customLogger.error(
        `Error processing Message for ${destination}: ${error.message}`,
        context,
      );
    }
  }

  /**
   * Message handler
   * @param record - The record to handle
   * @param sequenceNumber - The sequence number of the message
   * @returns Start the dapr server
   */
  public async handleMessage(
    record: CombinedDtoWithIndex,
    sequenceNumber: string | Array<string> | undefined,
  ): Promise<void> {
    incrementPendingMessageCount();
    const dateStart = Date.now();
    const context = DaprServiceApi.createLogContext('handleMessage');
    try {
      if (!checkPayloadConsistency(this.customLogger, context, record)) return;

      const { __source_table: sourceTable, __op: operation } = record;
      this.customLogger.debug(
        `Received - operation: ${operation} - payload: ${JSON.stringify(record)}`,
        context,
      );
      if (!sourceTable) return;

      const { mappedData, destination, ingestionEventTracking } =
        this.mappingService.mapData(sourceTable, record, this.plantList);
      // Check first if there is two table source in the mapping system
      // Fifo check
      this.customLogger.debug(
        `Mapped Data:${JSON.stringify(mappedData)}`,
        context,
      );
      if (!checkPlantConsistency(this.customLogger, mappedData, this.plantList))
        return;

      const newRecord = {
        destination,
        ingestionEventTracking,
        mappedData,
        operation,
        sourceTable,
      };
      await this.processMessage(newRecord, sequenceNumber);
    } catch (error) {
      this.customLogger.error(
        `Error handling Message: ${error.stack ?? error.message ?? JSON.stringify(error)}`,
        context,
      );
    } finally {
      if (record) {
        await execAndLog(
          this.customLogger,
          context,
          async () => {},
          {
            name: 'handleMessage function runtime',
            srcLocation: 'handleMessage',
          },
          {
            record,
          },
          dateStart,
        );
      }
      decrementPendingMessageCount();
    }
  }
}

import { Controller, Post, Req } from '@nestjs/common';
import { Request } from 'express';
import { DaprServiceApi } from './dapr-api-version.service';
import { AppLogger } from '@/common/logger/app-logger';
import { SubscribeMessageService } from '@/common/subscribe/subscribe.service';
import { EventhubSdkConfigService } from '@/config/eventhub-sdk/eventhub-sdk-config.service';
import { DaprService } from '@/dapr/dapr.service';
import { checkLabelType } from '@/helpers/validations/check-label-type';

// Environment variables
const bindings = {
  bindingTransferLog:
    process.env.INPUT_BINDINGS_MES_FAURECIA_DBO_TRANSFER_LOG_TRANSF_DI,
  topicPlants: process.env.TOPIC_PLANTS,
};

@Controller('')
export class DaprController {
  public constructor(
    private readonly eventhubSdkConfigService: EventhubSdkConfigService,
    private readonly daprService: DaprService,
    private readonly customLogger: AppLogger,
    private readonly subscribeMessageService: SubscribeMessageService,
    private readonly daprServiceApi: DaprServiceApi,
  ) {}

  /**
   * Process a standard event with common logging
   * @param request Request
   * @param methodName Method name for logging
   * @returns Promise<string>
   */
  private async processStandardEvent(
    request: Request,
    methodName: string,
  ): Promise<string> {
    const event = request.body;
    const context = DaprService.createLogContext('receiveEventTransferLog');
    if (checkLabelType(this.customLogger, context, event)) {
      await this.daprService.handleMessage(event);
      return `OK ${methodName}`;
    }
    return 'OK';
  }

  @Post(bindings.bindingTransferLog)
  public async receiveEventTransferLog(
    @Req() request: Request,
  ): Promise<string> {
    if (await this.eventhubSdkConfigService.useEventhubSDK()) {
      return 'OK USE EVENT HUB SDK';
    }
    return this.processStandardEvent(request, 'receiveEventTransferLog');
  }

  @Post(bindings.topicPlants)
  public async initPlant(@Req() request: Request): Promise<string> {
    const context = DaprService.createLogContext('initPlant');
    try {
      const data = request.body;
      await this.subscribeMessageService.handleMessage(data);
      await this.daprService.initializePlant();
      await this.daprServiceApi.initializePlant();

      this.customLogger.debug(`Updated Plants List`, context);
      return 'OK';
    } catch (error) {
      this.customLogger.error(
        `Error processing event: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }
}

