import { JobsLogContext } from '@mesx/common-lib';
import { MutexInterface, withTimeout, E_TIMEOUT } from 'async-mutex';
import { AppLogger } from '@/common/logger/app-logger';
import { MutexManagerService } from '@/common/mutex-manager/mutex-manager.service';
import { asyncSleep } from '@/common/sleep/sleep';

/**
 * Get the lock from mutex
 * @param logger application logger
 * @param context Job Log Context
 * @param serviceMutexes mutex register
 * @param key to get the right mutex instance
 * @param timeoutMs lock acquiring timeout
 * @param retryCount # of retry
 * @param retryDelayMs time between retries
 * @returns releaser function
 */
export async function acquireLockManagerWithTimeout(
  logger: AppLogger,
  context: JobsLogContext,
  serviceMutexes: MutexManagerService,
  key: string,
  timeoutMs = 9999,
  retryCount = 3, // Number of retry attempts
  retryDelayMs = 1000, // Delay between retries in milliseconds
): Promise<MutexInterface.Releaser | undefined> {
  let lastError: Error | undefined;
  let attempt = 1;

  const acquireLock = async (): Promise<
    MutexInterface.Releaser | undefined
  > => {
    try {
      const mutex = serviceMutexes.getMutex(key);
      return await withTimeout(mutex, timeoutMs).acquire();
    } catch (error) {
      lastError = error;
      if (error === E_TIMEOUT) {
        logger.warn(
          `Timeout while acquiring lock for ${key} (Attempt ${attempt} of ${retryCount})`,
          context,
        );
      } else {
        logger.error(
          `Error acquiring lock for ${key} (Attempt ${attempt} of ${retryCount}): ${error.message}`,
          context,
          error.stack,
        );
      }

      if (attempt < retryCount) {
        await asyncSleep(retryDelayMs);
        attempt += 1;
        return acquireLock();
      }
    }
    // Log the final failure
    if (lastError) {
      logger.error(
        `Failed to acquire lock for ${key} after ${retryCount} attempts: ${lastError.message}`,
        context,
      );
    }

    return undefined;
  };

  return acquireLock();
}

