import {
  JobsLogContext,
  RedisConnectionService,
  RedisClientInstance,
} from '@mesx/common-lib';
import { Injectable } from '@nestjs/common';
import { IngestionEventTrackingDTO } from './ingestion-event-tracking.dto.';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { RedisConfigService } from '@/config/redis/redis-sdk/redis-sdk.service';
import { exponentialBackoffRetry } from '@/helpers/retries/exponential-backoff-retry';

export type RedisCommandRawReply =
  | string
  | number
  | Buffer
  | null
  | undefined
  | Array<RedisCommandRawReply>;

export interface ReplyMap<T> {
  [key: string]: T;
}

export interface ReplyRecord<T> {
  [key: string]: T;
}

export type ReplyUnion =
  | string
  | number
  | Buffer
  | null
  | undefined
  | Array<ReplyUnion>
  | ReplyMap<ReplyUnion>
  | ReplyRecord<ReplyUnion>;
@Injectable()
export class IngestionEventTrackingService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: IngestionEventTrackingService.name,
      userId,
    };
  }

  public constructor(
    private readonly redisConfigService: RedisConfigService,
    private readonly redisConnectionFactory: RedisConnectionService,
    private readonly customLogger: AppLogger,
  ) {}

  private async getRedisClient(): Promise<RedisClientInstance> {
    const client = this.redisConnectionFactory.getClient();
    if (!client) {
      throw new Error('Redis client is not initialized.');
    }
    return client;
  }

  private async getIngestionEventTrackingByHashKeyCache(
    hashKey: string,
  ): Promise<Record<string, string> | null> {
    const context = IngestionEventTrackingService.createLogContext(
      'getIngestionEventTrackingByHashKeyCache',
    );
    try {
      const client = await this.getRedisClient();
      const operation = async (): Promise<Record<string, string>> =>
        client.hGetAll(`ingestion_event_tracking:${hashKey}`);
      const result = await exponentialBackoffRetry(
        this.customLogger,
        context,
        operation,
        5,
        100,
        true,
      ); // Retry 5 times with 1-second delay;
      return Object.keys(result).length > 0 ? result : null;
    } catch (error) {
      this.customLogger.error(
        `Error retrieving ingestion event tracking for redisKey ${hashKey}:${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  public async verifyAndTrackIngestionEventTrackingCache(
    ingestionEventTrackingDto: IngestionEventTrackingDTO,
  ): Promise<boolean> {
    const operationInfo = {
      name: 'Read IngestionEventTracking (Redis SDK)',
      srcLocation: 'verifyAndTrackIngestionEventTracking',
    };
    const context = IngestionEventTrackingService.createLogContext(
      'verifyAndTrackIngestionEventTrackingCache',
    );
    const {
      hashKey,
      lastTimestamp,
      changeLastLsn,
      keys,
      destinationTable,
      sourceTable,
    } = ingestionEventTrackingDto;
    const data = await execAndLog(
      this.customLogger,
      context,
      () => this.getIngestionEventTrackingByHashKeyCache(hashKey),
      operationInfo,
      { keys },
    );
    if (!data) {
      this.customLogger.debug(
        `No  ingestion event tracking  for key ${keys} hashKey ${hashKey} for source table ${sourceTable} to destination table ${destinationTable}. Proceeding.`,
        context,
      );
      return true;
    }
    const newLsn = BigInt(`0x${changeLastLsn}`);
    const existingTimestamp = Number(data.lastTimestamp);
    const existingLsn = BigInt(`0x${data.changeLastLsn}`);

    if (lastTimestamp < existingTimestamp) {
      this.customLogger.warn(
        [
          `Outdated timestamp for keys ${keys} for source table ${sourceTable} to destination table ${destinationTable}`,
          `Expected >= ${data.lastTimestamp},`,
          `received ${lastTimestamp}.`,
        ].join(' '),
        context,
      );
      return false;
    }
    if (lastTimestamp === existingTimestamp && newLsn <= existingLsn) {
      this.customLogger.warn(
        [
          `Outdated or duplicate LSN for key ${keys}.`,
          `Expected > ${existingLsn}, received ${changeLastLsn} for source table ${sourceTable} to destination table ${destinationTable}.`,
        ].join(' '),
        context,
      );
      return false;
    }
    return true;
  }

  public async upsertCache(
    ingestionEventTrackingDto: IngestionEventTrackingDTO,
  ): Promise<void> {
    const context =
      IngestionEventTrackingService.createLogContext('upsertCache');
    const { hashKey, ...data } = ingestionEventTrackingDto;
    const { statePrefix } = this.redisConfigService;
    const ttlSecondes =
      await this.redisConfigService.dataIngestionWorkdataTtlSecondes();
    const redisKey = `${statePrefix}|${hashKey}`;

    try {
      const operationInfo = {
        name: 'Upsert IngestionEventTracking (Redis SDK)',
        srcLocation: 'IngestionEventTracking.upsert',
      };

      const client = await this.getRedisClient();

      const operation = async (): Promise<Array<RedisCommandRawReply>> => {
        const multi = client.multi();
        multi.hSet(redisKey, data);
        multi.expire(redisKey, ttlSecondes);

        const result = await multi.exec();

        if (result === null) {
          throw new Error(
            'Redis MULTI.exec() returned null — transaction failed.',
          );
        }

        // Transform each element into RedisCommandRawReply
        return result.map((reply) =>
          this.transformReply(reply as unknown as ReplyUnion),
        );
      };

      await execAndLog(
        this.customLogger,
        context,
        () =>
          exponentialBackoffRetry(
            this.customLogger,
            context,
            operation,
            5,
            100,
            true,
          ),
        operationInfo,
      );
    } catch (error) {
      this.customLogger.error(
        `Error upserting ingestion event tracking for redisKey ${redisKey} with TTL ${ttlSecondes}: ${error.message}`,
        context,
        error.stack,
      );
      throw error;
    }
  }

  /**
   * Recursively transforms a ReplyUnion into a RedisCommandRawReply.
   * @param reply - The Redis reply to transform
   * @returns A RedisCommandRawReply object
   */
  private transformReply(reply: ReplyUnion): RedisCommandRawReply {
    if (
      reply === null ||
      reply === undefined ||
      typeof reply === 'string' ||
      typeof reply === 'number' ||
      Buffer.isBuffer(reply)
    ) {
      return reply;
    }

    if (Array.isArray(reply)) {
      return reply.map((r) => this.transformReply(r));
    }

    if (typeof reply === 'object') {
      return Object.entries(reply).map(([k, v]) => [k, this.transformReply(v)]);
    }

    return null;
  }
}

