import { Repository } from 'typeorm';
import { telemetryMetrics, PROCESSING_STATUS } from '../../open-telemetry';
import { Transfer } from './transfer-log.entity';
import { execAndLog } from '@/common/exec-and-log/exec-and-log';
import { AppLogger } from '@/common/logger/app-logger';
import { TransferMessage } from '@/common/publish-message/interface/publish-transfer.interface';
import { PublishMessageService } from '@/common/publish-message/publish-message.service';
import { EventhubService } from '@/config/eventhub/eventhub.service';

@Injectable()
export class TransferLogService {
  private static createLogContext(
    method: string,
    plant?: number,
    object?: string,
    userId?: string,
  ): JobsLogContext {
    return {
      method,
      object,
      plant,
      service: TransferLogService.name,
      userId,
    };
  }

  public constructor(
    @InjectRepository(Transfer)
    private readonly transferLogRepository: Repository<Transfer>,
    private readonly customLogger: AppLogger,
    private readonly publishMessageService: PublishMessageService,
    private readonly eventhubService: EventhubService,
  ) {}

  @OnEvent('transfer.c')
  private async create(payload: Transfer): Promise<void> {
    const context = TransferLogService.createLogContext(
      'create',
      payload?.plant,
    );

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const operationInfo = {
      name: 'Create TransferLog (SQL)',
      srcLocation: 'transfer',
    };

    try {
      const { ...transferLogData } = payload;
      const transferMessage: TransferMessage = {
        containerId: transferLogData.containerId,
        transferId: transferLogData.transferId,
        plant: transferLogData.plant,
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTransfer,
        transferMessage,
      );
      const sqlStartTime = Date.now();
      await execAndLog(
        this.customLogger,
        context,
        () => this.transferLogRepository.save(transferLogData),
        operationInfo,
      );
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(transferLogData.plant),
        'transfer',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(transferLogData.plant),
        'transfer',
      );
    } catch (error) {
      this.customLogger.error(
        `error in insert in data base and publish message: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('transfer.u')
  private async updateBytransferIdAndPlant(payload: Transfer): Promise<void> {
    const context = TransferLogService.createLogContext(
      'updateBytransferIdAndPlant',
      payload?.plant,
    );

    const operationInfo = {
      name: '',
      srcLocation: 'TransferLog.u',
    };

    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);

    const { transferId, plant, containerId } = payload;

    try {
      const { ...transferLogData } = payload;
      const transferMessage: TransferMessage = {
        containerId: transferLogData.containerId,
        transferId: transferLogData.transferId,
        plant: transferLogData.plant,
      };
      await this.publishMessageService.publishMessage(
        this.eventhubService.topicTransfer,
        transferMessage,
      );
      operationInfo.name = 'Update TransferLog (SQL)';
      // Update using the nonclustered key columns (plant, containerId, transferId)
      const sqlStartTime = Date.now();
      const result = await execAndLog(
        this.customLogger,
        context,
        () =>
          this.transferLogRepository.update(
            { plant, containerId, transferId },
            transferLogData,
          ),
        operationInfo,
        { transferLogData },
      );

      if (result.affected === 0) {
        return undefined;
      }
      const sqlDuration = Date.now() - sqlStartTime;

      // Track SQL operation metric using the singleton
      telemetryMetrics.trackEventProcessingDuration(
        sqlDuration,
        PROCESSING_STATUS.SQL,
        String(plant),
        'transfer',
      );
      telemetryMetrics.trackEventProcessed(
        PROCESSING_STATUS.SQL,
        String(plant),
        'transfer',
      );
    } catch (error) {
      this.customLogger.error(
        `Error updating transfer: ${error.message}`,
        context,
        error.stack,
      );
    }
    return undefined;
  }

  @OnEvent('transfer.r')
  private async readSnapshot(payload: Transfer): Promise<void> {
    const context = TransferLogService.createLogContext(
      'updateBytransferIdAndPlant',
      payload?.plant,
    );
    if (!payload)
      return this.customLogger.error(`payload is empty${payload}`, context);
    return undefined;
  }
}

