import { PeriodicExportingMetricReader } from '@opentelemetry/sdk-metrics';
import { NodeSDK } from '@opentelemetry/sdk-node';
import {
  BatchSpanProcessor,
  ParentBasedSampler,
  TraceIdRatioBasedSampler,
} from '@opentelemetry/sdk-trace-base';
import type {
  SpanExporter,
  SpanProcessor,
} from '@opentelemetry/sdk-trace-base';
import { ATTR_SERVICE_NAME } from '@opentelemetry/semantic-conventions';
import { MetricDimensions } from './interfaces/metric-dimensions.interface';
import {
  TelemetryConfig,
  TelemetryConfigLoader,
  TelemetryInitResult,
  TelemetryMetricsConfig,
} from './interfaces/telemetry-config.interface';

let telemetryInitialized = false;
let initializedServiceName: string | undefined;
let telemetrySDK: NodeSDK | undefined;

const DEFAULT_IGNORE_INCOMING_URLS = [
  '/probes',
  '/dapr/subscribe',
  '/metadata/identity/oauth2/token',
];

/**
 * Returns whether telemetry has been initialized.
 * @returns True if telemetry is initialized, false otherwise.
 */
export function isTelemetryInitialized(): boolean {
  return telemetryInitialized;
}

/**
 * Returns the service name that was used when telemetry was initialized.
 * @returns The service name, or undefined if telemetry has not been initialized.
 */
export function getInitializedServiceName(): string | undefined {
  return initializedServiceName;
}

/**
 * Returns whether the configured OTLP protocol is gRPC.
 * @returns True if the protocol is gRPC, false otherwise.
 */
function isGrpcProtocol(): boolean {
  return (
    process.env.OTEL_EXPORTER_OTLP_PROTOCOL?.toLowerCase().trim() === 'grpc'
  );
}

/**
 * Builds the OTLP trace exporter based on the configured protocol.
 * @returns A gRPC or HTTP OTLP trace exporter.
 */
function buildTraceExporter(): SpanExporter {
  return isGrpcProtocol()
    ? new GrpcOTLPTraceExporter()
    : new OTLPTraceExporter();
}

/**
 * Builds the OTLP metric reader based on the configured protocol.
 * @returns A PeriodicExportingMetricReader configured with the appropriate exporter.
 */
function buildMetricReader(): PeriodicExportingMetricReader {
  const exporter = isGrpcProtocol()
    ? new GrpcOTLPMetricExporter()
    : new OTLPMetricExporter();
  return new PeriodicExportingMetricReader({ exporter });
}

/**
 * Builds the HTTP instrumentation config with URL ignore rules.
 * @param config - The telemetry configuration containing ignore URL patterns.
 * @returns An HttpInstrumentationConfig with request hooks applied.
 */
function buildHttpInstrumentation(
  config: TelemetryConfig,
): HttpInstrumentationConfig {
  const ignoreIncoming =
    config.ignoreIncomingUrls ?? DEFAULT_IGNORE_INCOMING_URLS;
  const ignoreOutgoing = config.ignoreOutgoingUrls ?? [];

  return {
    ignoreIncomingRequestHook: (request: IncomingMessage): boolean => {
      if (request.method === 'OPTIONS') return true;
      if (request.url === '/') return true;
      const url = request.url ?? '';
      return ignoreIncoming.some((pattern) => url.includes(pattern));
    },
    ignoreOutgoingRequestHook: (options: RequestOptions): boolean => {
      const path = options.path ?? '';
      return ignoreOutgoing.some((pattern) => path.includes(pattern));
    },
  };
}

/**
 * Builds the list of span processors for the trace pipeline.
 * @param config - The telemetry configuration, including any custom span processors.
 * @param traceExporter - The trace exporter to use in the BatchSpanProcessor.
 * @returns An array of SpanProcessor instances.
 */
function buildSpanProcessors(
  config: TelemetryConfig,
  traceExporter: SpanExporter,
): Array<SpanProcessor> {
  const processors: Array<SpanProcessor> = [
    new BatchSpanProcessor(traceExporter),
  ];

  if (config.customSpanProcessors?.length) {
    processors.push(...config.customSpanProcessors);
  }

  return processors;
}

/**
 * Initializes the OpenTelemetry SDK with the provided configuration.
 * @param config - The telemetry configuration options.
 * @returns A TelemetryInitResult indicating success or failure.
 */
export function initializeTelemetry(
  config: TelemetryConfig,
): TelemetryInitResult {
  if (telemetryInitialized) {
    return {
      success: true,
      serviceName: initializedServiceName,
    };
  }

  if (!config.enableTelemetry) {
    return {
      success: true,
      error: 'Telemetry disabled',
    };
  }

  if (!config.serviceName) {
    const error = 'Service name is required';
    console.error(`[Telemetry] ${error}`);
    return {
      success: false,
      error,
    };
  }

  try {
    const hostName = config.hostName ?? os.hostname();
    const HOST_NAME_ATTRIBUTE = 'host.name';
    const traceExporter = buildTraceExporter();

    const sdkOptions: ConstructorParameters<typeof NodeSDK>[0] = {
      resource: resourceFromAttributes({
        [ATTR_SERVICE_NAME]: config.serviceName,
        [HOST_NAME_ATTRIBUTE]: hostName,
      }),
      sampler: new ParentBasedSampler({
        root: new TraceIdRatioBasedSampler(config.samplingRatio ?? 1),
      }),
      spanProcessors: buildSpanProcessors(config, traceExporter),
      instrumentations: [
        new HttpInstrumentation(buildHttpInstrumentation(config)),
      ],
    };

    if (config.enableMetrics ?? false) {
      sdkOptions.metricReaders = [buildMetricReader()];
    }

    const sdk = new NodeSDK(sdkOptions);
    sdk.start();
    telemetrySDK = sdk;

    telemetryInitialized = true;
    initializedServiceName = config.serviceName;
    return {
      success: true,
      serviceName: config.serviceName,
    };
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    return {
      success: false,
      error: message,
    };
  }
}

/**
 * Bootstraps telemetry by loading configuration asynchronously and initializing the SDK.
 * @param loader - An async function that resolves the telemetry configuration.
 * @returns A TelemetryInitResult indicating success or failure.
 */
export async function bootstrapTelemetry(
  loader: TelemetryConfigLoader,
): Promise<TelemetryInitResult> {
  try {
    const config = await loader();
    return initializeTelemetry(config);
  } catch (error) {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`[Telemetry] Failed to load configuration: ${message}`);
    return {
      success: false,
      error: `Config loader failed: ${message}`,
    };
  }
}

/**
 *
 */
export async function shutdownTelemetry(): Promise<void> {
  if (telemetrySDK) {
    await telemetrySDK.shutdown();
  }
}

/**
 *
 */
export function resetTelemetryState(): void {
  telemetryInitialized = false;
  initializedServiceName = undefined;
  telemetrySDK = undefined;
}

class TelemetryMetricsServiceImpl {
  private containerHost = '';

  private meter: Meter | undefined = undefined;

  private serviceName = '';

  private initialized = false;

  private readonly counters: Map<string, Counter> = new Map();

  private readonly histograms: Map<string, Histogram> = new Map();

  public initialize(config: TelemetryMetricsConfig): void {
    if (this.initialized) {
      return;
    }

    this.serviceName = config.serviceName;
    this.containerHost = config.hostName ?? os.hostname();
    this.meter = metrics.getMeter(`${config.serviceName}-metrics`);
    this.initialized = true;
  }

  public isInitialized(): boolean {
    return this.initialized;
  }

  public getServiceName(): string {
    return this.serviceName;
  }

  private buildDimensions(
    dimensions: MetricDimensions,
  ): Record<string, string> {
    const result: Record<string, string> = {
      containerHost: this.containerHost,
    };

    if (dimensions.plantCode) result.plantCode = dimensions.plantCode;
    if (dimensions.status) result.status = dimensions.status;
    if (dimensions.topic) result.topic = dimensions.topic;
    if (dimensions.partitionId) result.partitionId = dimensions.partitionId;

    return result;
  }

  private getCounter(name: string): Counter | undefined {
    if (!this.meter) return undefined;

    let counter = this.counters.get(name);
    if (!counter) {
      counter = this.meter.createCounter(name, {
        description: `Counter for ${name}`,
      });
      this.counters.set(name, counter);
    }
    return counter;
  }

  private getHistogram(name: string, unit = 'ms'): Histogram | undefined {
    if (!this.meter) return undefined;

    let histogram = this.histograms.get(name);
    if (!histogram) {
      histogram = this.meter.createHistogram(name, {
        description: `Histogram for ${name}`,
        unit,
      });
      this.histograms.set(name, histogram);
    }
    return histogram;
  }

  public trackCounter(
    name: string,
    value: number,
    dimensions: MetricDimensions = {},
  ): void {
    if (!this.initialized) {
      return;
    }

    try {
      const counter = this.getCounter(name);
      if (counter) {
        counter.add(value, this.buildDimensions(dimensions));
      }
    } catch (error) {
      console.warn(
        `[TelemetryMetrics] Failed to track counter ${name}:`,
        (error as Error).message,
      );
    }
  }

  public trackHistogram(
    name: string,
    value: number,
    dimensions: MetricDimensions = {},
    unit = 'ms',
  ): void {
    if (!this.initialized) {
      return;
    }

    try {
      const histogram = this.getHistogram(name, unit);
      if (histogram) {
        histogram.record(value, this.buildDimensions(dimensions));
      }
    } catch (error) {
      console.warn(
        `[TelemetryMetrics] Failed to track histogram ${name}:`,
        (error as Error).message,
      );
    }
  }

  public trackEventProcessed(
    status: PROCESSING_STATUS,
    plantCode?: string,
    topic?: string,
    partitionId?: string,
  ): void {
    this.trackCounter('event_processed_count', 1, {
      status,
      plantCode,
      topic,
      partitionId,
    });
  }

  public trackEventProcessingDuration(
    durationMs: number,
    status: PROCESSING_STATUS,
    plantCode?: string,
    topic?: string,
    partitionId?: string,
  ): void {
    this.trackHistogram('event_processing_duration_ms', durationMs, {
      status,
      plantCode,
      topic,
      partitionId,
    });
  }

  public reset(): void {
    this.initialized = false;
    this.serviceName = '';
    this.containerHost = '';
    this.meter = undefined;
    this.counters.clear();
    this.histograms.clear();
  }
}

export const telemetryMetrics = new TelemetryMetricsServiceImpl();

